input-validation.code:
import json
import sys

def validate_age(value):
    # Reject bool and every non-int with: age must be an integer
    # Reject integers outside 0..120 with: age must be between 0 and 120
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError("age must be an integer")
    if not 0 <= value <= 120:
        raise ValueError("age must be between 0 and 120")
    return value

raw = sys.stdin.read().strip()
values = [json.loads(raw)] if raw else [25, "25", -3, 200]
for value in values:
    try:
        print(f"accepted: {validate_age(value)!r}")
    except ValueError as error:
        print(f"rejected: {error}")

